DDATA = json.loads(zlib.decompress(base64.b64decode("")))
DATA_V5 = ROOT / "datasets/drafting-v5"
DATA_V5.mkdir(parents=True, exist_ok=True)
for name, content in DDATA.items():
    target = DATA_V5 / name
    if target.exists():
        assert target.read_text(encoding="utf-8") == content
    else:
        target.write_text(content, encoding="utf-8")
print(validate_splits(load_trajectories(DATA_V5 / "train.jsonl"), load_trajectories(DATA_V5 / "validation.jsonl")))
RUN_V5 = ROOT / "runs/drafting-v5-150steps"
INIT_V5 = RUN_V4 / "adapter-step150"
assert not RUN_V5.exists()
assert hashlib.sha256(Path(str(INIT_V5)+".safetensors").read_bytes()).hexdigest() == "b368303a7bf659a6bc76e4e5ec8a1b5f5c728d80f4f9bfea62de31dd6f81c966"
args_v5 = [sys.executable, "-u", "-m", "forge.train_tools", "--train", str(DATA_V5 / "train.jsonl"), "--validation", str(DATA_V5 / "validation.jsonl"), "--llm-dir", str(MODEL), "--out", str(RUN_V5), "--init-adapter", str(INIT_V5), "--languages", "en", "--steps", "150", "--batch", "1", "--accum", "8", "--max-length", "2048", "--rank", "16", "--alpha", "32", "--lr", "0.00005", "--gradient-checkpointing", "--checkpoint-every", "50", "--log-every", "25", "--max-runtime-minutes", "15"]
with subprocess.Popen(args_v5, cwd=WORK, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1) as process:
    for line in process.stdout:
        print(line, end="", flush=True)
    rc_v5 = process.wait()
assert rc_v5 == 0
